(function(){
'use strict';
const R=window.PEPRules,D=R.DATA,$=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[\u2013\u2014]/g,'-').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>String(R.round(n));
let state=R.fresh(),dirty=false,toastTimer,sectionObserver,activeSection='personal';
const logo=document.querySelector('.masthead img').src;
function get(path){return path.split('.').reduce((v,k)=>v?.[k],state);}
function set(path,value){const a=path.split('.');let o=state;for(const k of a.slice(0,-1))o=o[k];o[a.at(-1)]=value;dirty=true;}
function field(path,label,type='text',help='',full=false){let id=path.replaceAll('.','-');return `<div class="field${full?' full':''}"><label for="${id}">${label}</label><input id="${id}" data-bind="${path}" type="${type}" value="${esc(get(path))}" ${type==='number'?'min="1" step="1"':''} maxlength="500">${help?`<p class="help">${help}</p>`:''}</div>`;}
function area(path,label,help=''){return `<div class="field full"><label for="${path.replaceAll('.','-')}">${label}</label><textarea id="${path.replaceAll('.','-')}" data-bind="${path}" maxlength="10000">${esc(get(path))}</textarea>${help?`<p class="help">${help}</p>`:''}</div>`;}
function select(path,label,options,help=''){return `<div class="field"><label for="${path.replaceAll('.','-')}">${label}</label><select id="${path.replaceAll('.','-')}" data-bind="${path}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(get(path))===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select>${help?`<p class="help">${help}</p>`:''}</div>`;}
function toast(msg){clearTimeout(toastTimer);$('toast').textContent=msg;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,6000);}
function personal(){const spec=D.specializations[state.student.specialization];return `<section id="personal"><h2>1. Personal details</h2><p class="intro">Build your proposed 120 EC programme. Required courses and checks adapt to your choices. Use <strong>Save draft</strong> to download your entries as a separate editable file, and <strong>Open draft</strong> to restore them. Typing into this form does not change the HTML file.</p><div class="grid">${field('student.firstName','First name')}${field('student.lastName','Last name')}${field('student.number','Student number')}${select('student.specialization','Specialisation',[['','Select specialisation'],...Object.entries(D.names)])}${spec&&Object.keys(spec.paths).length?select('student.path','Path',[['','Select path'],...Object.keys(spec.paths).map(p=>[p,D.paths[p]])]):''}<div class="field"><label for="cohort">Cohort (start year)</label><input id="cohort" value="2026" readonly></div>${select('student.education','Previous education',[['','Select previous education'],['VU_FW','VU bachelor - Farmaceutische Wetenschappen'],['WO','Other university bachelor'],['HBO','HBO / university of applied sciences diploma']])}${field('student.institution','Previous institution')}${field('student.degree','Degree')}${field('student.graduated','Graduation date','date')}</div></section>`;}
function principles(){
 const codes=R.principleCodes(state),nonVU=['WO','HBO'].includes(state.student.education),record=R.principlesStatementRequired(state);
 return `<section id="principles"><h2>2. Principles courses</h2><p class="help">Students with a VU bachelor Farmaceutische Wetenschappen are not allowed to follow any of the Principles courses. Students with another background should follow both Principles courses. If the admission board deviates from this, this decision should be recorded on the PEP form by the Admissions board. In that case, only the admission board completes the decision field and signature in the downloaded PDF.</p>${!state.student.education?'<p class="help">Select your previous education in Personal details first.</p>':''}${nonVU?`<div class="inset"><p class="help">Both Principles are selected by default for a non-VU Pharmaceutical Sciences background; adjust the selection only if decided by the Admissions board. The specialisation coordinator arranges the signature by the Admissions Board.</p>${selectionBlock('principles',D.principles,codes)}${record?'<div class="notice principles-warning" role="alert"><strong>Admissions Board permission required</strong><p>Only omit one or both Principles courses if the Admissions Board has indicated that you are allowed to skip them. The Admissions Board must record its decision and formally sign the downloaded PDF. Your specialisation coordinator arranges this decision and signature before preapproving the PEP.</p></div>':''}</div>`:''}${state.student.education?`<p class="section-subtotal">Principles courses in this plan: ${codes.length*6} EC</p>`:''}</section>`;
}
function gearIcon(){return '<svg class="action-icon double-cog" aria-hidden="true" focusable="false" viewBox="0 0 34 30" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round"><g transform="translate(11 11)"><path d="M-2-9H2L2.7-6.7 4.7-5.8 6.8-6.6 9-2.8 7.2-1.2V1.2L9 2.8 6.8 6.6 4.7 5.8 2.7 6.7 2 9H-2L-2.7 6.7-4.7 5.8-6.8 6.6-9 2.8-7.2 1.2V-1.2L-9-2.8-6.8-6.6-4.7-5.8-2.7-6.7Z"/><circle r="3.2"/></g><g transform="translate(24 20) scale(.78)"><path fill="white" d="M-2-9H2L2.7-6.7 4.7-5.8 6.8-6.6 9-2.8 7.2-1.2V1.2L9 2.8 6.8 6.6 4.7 5.8 2.7 6.7 2 9H-2L-2.7 6.7-4.7 5.8-6.8 6.6-9 2.8-7.2 1.2V-1.2L-9-2.8-6.8-6.6-4.7-5.8-2.7-6.7Z"/><circle r="3.2"/></g></svg>';}
function removeIcon(){return '<svg class="action-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"><path d="m6 6 12 12 M18 6 6 18"/></svg>';}
function majorAdded(){return R.isEducation(state)?state.major.enabled!==false:['single','split'].includes(state.major.route);}
function smcReminderNeeded(){return state.student.specialization==='DSDD'&&state.student.path==='SMC'&&majorAdded()&&!state.major.smcPreparationAcknowledged;}
function smcReminder(){return smcReminderNeeded()?'<div id="smc-preparation-reminder" class="notice principles-warning smc-reminder" role="status"><strong>Research project preparation reminder</strong><p>For a Synthetic Radiopharmaceutical Chemistry internship, Advanced Radiopharmaceutical Chemistry is required preparation. Discuss this with the internship coordinator.</p><button data-action="acknowledge-smc">Acknowledge</button></div>':'';}
function courseRows(codes,{removable=false,removeAction='remove-elective',required=[],custom=[]}={}){
 const actions=removable||custom.length>0;
 return `<div class="included-pep"><div class="course-table-wrap"><table class="course-table"><thead><tr><th scope="col">Course name</th><th scope="col" class="course-code">Course code</th><th scope="col" class="course-level">Level</th>${actions?'<th scope="col" class="actions">Action</th>':''}<th scope="col" class="ec">EC</th></tr></thead><tbody>${codes.map(code=>{
 const c=R.map[code];
 if(!c)return `<tr><td colspan="3">Unrecognized code: ${esc(code)}</td>${actions?`<td><button data-action="${removeAction}" data-code="${esc(code)}">Remove</button></td>`:''}<td>-</td></tr>`;
 return `<tr data-course-code="${esc(code)}"><td><span class="course-name">${esc(c.name)}</span>${required.includes(code)?'<span class="tag">Required for path</span>':''}</td><td class="course-code">${esc(code)}</td><td class="course-level">${c.level}</td>${actions?`<td class="actions"><button class="row-action" data-action="${removeAction}" data-code="${esc(code)}" aria-label="Remove ${esc(c.name)}" title="Remove ${esc(c.name)}">${removeIcon()}</button></td>`:''}<td class="ec">${c.ec}</td></tr>`;
 }).join('')}${custom.map(c=>customCourseRow(c)).join('')}</tbody></table></div></div>`;
}
function selectionBlock(kind,codes,selected,custom=[]){const names={principles:'Principles course',constrained:R.isEducation(state)?'constrained course':'constrained elective',education:'Education elective'};return `${selected.length||custom.length?courseRows(selected,{removable:true,removeAction:'remove-'+kind,required:kind==='constrained'?R.pathCodes(state):[],custom}):'<p class="empty">No courses added to this part of your PEP.</p>'}${kind==='principles'&&codes.every(c=>selected.includes(c))?'':`<button id="pick-${kind}" data-action="pick-course" data-kind="${kind}" class="add-course-button">+ ${kind==='constrained'&&R.isEducation(state)&&selected.length?'Choose another constrained course':'Add '+names[kind]}</button>`}`;}
function compulsory(){if(R.isEducation(state))return `<section id="compulsory"><h2>3. Compulsory courses</h2><h3>DDS component · 12 EC</h3>${courseRows(R.educationSpec().compulsory,{})}<h3>Education component · 54 EC</h3>${courseRows(R.educationSpec().educationCompulsory,{})}<p class="help">All listed courses are fixed, including Peergroup 1, Peergroup 2 and Startweek at 0 EC. Exemptions are requested separately; exempted courses remain included.</p></section>`;const codes=R.requiredCodes(state).filter(c=>!D.principles.includes(c));return `<section id="compulsory"><h2>3. Compulsory courses</h2>${codes.length?courseRows(codes,{}):'<p class="empty">Choose a specialisation to see your compulsory courses.</p>'}<p class="help">These compulsory VU courses and their EC are fixed and cannot be omitted. Exemptions are requested separately; exempted courses remain included with their normal EC.</p></section>`;}
function constrained(){
 if(R.isEducation(state))return `<section id="constrained"><h2>4. Constrained electives</h2><p class="help">Choose one course (6 EC) for the DDS component. <span class="required-mark">* Required choice.</span> The other course may be added under DDS electives if it fits the 60 EC DDS component.</p>${selectionBlock('constrained',R.educationSpec().constrained,state.constrained)}<p class="section-subtotal">${state.constrained.length} / 1 course selected · ${state.constrained.length*6} EC</p></section>`;

 const spec=D.specializations[state.student.specialization],required=R.pathCodes(state);
 if(R.needsPath(state))return `<section id="constrained"><h2>4. Constrained electives</h2><p class="notice"><strong>Select your path first.</strong> For ${esc(state.student.specialization)}, the available choices and required courses depend on your path. <a href="#personal">Choose your path in Personal details</a> to continue.</p></section>`;
 return `<section id="constrained"><h2>4. Constrained electives</h2><p class="help">Select two or more courses (min. 12 EC) here. Required path courses are already preselected if applicable.</p>${state.student.path==='MP'?'<p class="help">Molecular Pharmacology requires Drug Target Biochemistry &amp; Signalling. Choose at least one of the other five courses as an additional constrained elective.</p>':''}${spec?`${selectionBlock('constrained',spec.constrained,state.constrained)}<p class="section-subtotal">${state.constrained.length} courses selected · minimum 2 · ${state.constrained.length*6} EC</p>`:'<p class="empty">Choose a specialisation first.</p>'}</section>`;
}
function projectSummary(key){const p=state[key];const detail=field=>p[field+'Status']==='unknown'?'Not yet known':['proposed','confirmed'].includes(p[field+'Status'])&&p[field]?esc(p[field])+' ('+esc(p[field+'Status'])+')':'Details required';return `<div class="project-summary"><span><strong>Host:</strong> ${detail('host')}</span><span><strong>Topic:</strong> ${detail('topic')}</span></div>`;}
function projectTable(){const groups=['major','minor','literature'].filter(key=>key==='major'?majorAdded():!R.isEducation(state)&&state[key].enabled);if(!groups.length)return '';return `<div class="included-pep"><div class="course-table-wrap"><table class="course-table projects-table ${majorAdded()?'major-course-table':''}"><thead><tr><th>Course name</th><th class="course-code">Course code</th><th class="course-level">Level</th><th class="actions">Action</th><th class="ec">EC</th></tr></thead><tbody>${groups.map(key=>{const label=key==='major'?'Major research project':key==='minor'?'Minor research project':'Literature thesis',rows=R.components(state).filter(r=>r.section===label[0].toUpperCase()+label.slice(1));return `${rows.map((r,index)=>`<tr data-project="${esc(r.id)}" data-project-key="${key}"><td><span class="course-name">${esc(r.name)}</span>${projectSummary(key)}</td><td class="course-code">${esc(r.code)}</td><td class="course-level">${r.level??(key==='minor'?500:600)}</td><td class="actions">${index===0?`<button id="edit-project-${key}" class="row-action" data-action="project" data-key="${key}" aria-label="Edit details for ${esc(label)}" title="Edit details">${gearIcon()}</button><button class="row-action" data-action="remove-project" data-key="${key}" aria-label="Remove ${esc(label)}" title="Remove ${esc(label)}">${removeIcon()}</button>`:''}</td><td class="ec">${r.ec}</td></tr>`).join('')}`;}).join('')}</tbody></table></div></div>`;}
function projects(){if(R.isEducation(state))return educationProjects();return `<section id="projects"><h2>5. Research projects and literature thesis</h2><p class="help">Use + Add major research project to enter the registration route, proposed or confirmed host and topic status. Use the double-cog button to edit a project already included in your PEP. “Not yet known” is allowed for the topic. Only courses in the blue areas are included in your PEP.</p>${projectTable()}<div class="project-additions">${!majorAdded()?'<button id="add-major" data-action="project" data-key="major">+ Add major research project · 48 EC (compulsory)</button>':''}${!state.minor.enabled?'<button id="add-minor" data-action="project" data-key="minor">+ Add minor research project · 30 EC</button>':''}${!state.literature.enabled?'<button id="add-literature" data-action="project" data-key="literature">+ Add literature thesis · 12 EC</button>':''}</div>${state.literature.enabled?'<p class="help">The literature thesis is independent of the internship and has a different topic.</p>':''}${state.minor.enabled&&state.literature.enabled?'<p class="notice warning-text"><strong>Strongly discouraged:</strong> combining a major research project, minor research project and literature thesis cannot be completed within the two-year programme and will result in study delay, even when the EC total fits.</p>':''}<details class="help entry-reminders"><summary>Entry and supervision reminders</summary><p>TER Article 8.1 requires at least 18 EC should be obtained from the programme to be able to start with a major or minor research project or a literature thesis. Major Part 1 must be passed before Part 2. Internship suitability, results and scheduling are checked through the existing internship process.</p></details></section>`;}
function educationProjects(){return `<section id="projects"><h2>5. Major research project</h2><p class="help">Use + Add major research project to enter the host and topic details. The 30 EC enter your PEP only when you save the popup.</p>${majorAdded()?projectTable():'<button id="add-major" data-action="project" data-key="major">+ Add major research project · 30 EC (compulsory)</button>'}<p class="help">Education has a fixed 30 EC major (XM_0200). Minor research projects and literature theses are not available.</p>${state.minor.enabled?'<p class="notice warning-text">This plan contains a prohibited minor.</p><button data-action="remove-education-minor">Remove minor research project</button>':''}<details class="help entry-reminders"><summary>Entry and language reminders</summary><p>At least 18 EC must be obtained from the programme before starting the major research project (TER Article 8.1). Education is taught in English in year 1 and Dutch in year 2; Dutch-language admission requirements apply. Eligibility is checked through the existing admission and internship processes.</p></details></section>`;}
function availableElectives(category){const spec=D.specializations[state.student.specialization],excluded=new Set([...R.requiredCodes(state),...state.constrained,...(R.isEducation(state)?[]:(spec?.constrained||[])),...state.electives,'XM_0198',...D.principles,'XM_0196']);return D.courses.filter(c=>c.category===category&&!excluded.has(c.code)&&(!R.isEducation(state)||R.availableDDS(state).includes(c.code))).sort((a,b)=>a.name.localeCompare(b.name));}
function picker(category){return `<button id="pick-${category}" data-action="pick-course" data-kind="${category}" class="add-course-button">+ Add ${category==='alpha'?'alpha/gamma':'general'} elective</button>`;}
function pickerCodes(kind){if(kind==='principles')return ['WO','HBO'].includes(state.student.education)?D.principles.filter(c=>!R.principleCodes(state).includes(c)):[];if(kind==='constrained')return R.needsPath(state)?[]:(D.specializations[state.student.specialization]?.constrained||[]).filter(c=>!state.constrained.includes(c));if(kind==='education')return R.isEducation(state)?R.educationSpec().educationElectives.filter(c=>!state.educationElectives.includes(c)):[];return availableElectives(kind).map(c=>c.code);}
let pickerReturnId='';
function coursePicker(kind,keepOpen=false,message=''){const editor=$('editor'),wasOpen=editor.open,scrollTop=editor.scrollTop;if(!keepOpen)pickerReturnId=document.activeElement?.id||'';const title={principles:'Add a Principles course',constrained:R.isEducation(state)?'Choose one constrained course':'Add constrained electives',education:'Add Education electives',general:R.isEducation(state)?'Add DDS electives':'Add general electives',alpha:'Add alpha/gamma electives'}[kind];const codes=pickerCodes(kind);editor.innerHTML=`<button id="dlg-close" class="dialog-close" type="button" data-action="close-picker">Close</button><h2 id="dialog-title">${esc(title)}</h2><p class="help">Use + Add to include courses in your PEP. Added courses disappear from these options. Choose Done when finished.${kind==='education'?' Wereldburgerschap and deel 2 are added together.':''}${kind==='constrained'&&R.isEducation(state)?' Choosing another course replaces the existing constrained choice.':''}</p><p class="picker-feedback" role="status" aria-live="polite">${esc(message)}</p>${codes.length?`<div class="available-courses">${codes.map(code=>{const c=R.map[code];return `<div class="available-course"><div><strong class="course-name">${esc(c.name)}</strong><span class="course-institution">${esc(code)} · Level ${c.level} · ${c.ec} EC</span></div><button type="button" data-action="add-choice" data-kind="${kind}" data-code="${esc(code)}" aria-label="Add ${esc(c.name)}">+ Add</button></div>`;}).join('')}</div>`:'<p class="empty">All courses in this list are already included in your PEP.</p>'}<div class="picker-footer"><button type="button" data-action="close-picker">Close</button><button type="button" id="picker-done" class="primary" data-action="close-picker">Done</button></div>`;if(!wasOpen)editor.showModal();else{editor.scrollTop=scrollTop;(editor.querySelector('[data-action="add-choice"]')||$('picker-done')).focus({preventScroll:true});}}
function changeSelection(kind,code,adding){if(kind==='principles'){const current=R.principleCodes(state);state.principles.override=true;state.principles.required=adding?[...new Set([...current,code])]:current.filter(c=>c!==code);}else if(kind==='constrained'){state.constrained=R.isEducation(state)&&adding?[code]:adding?[...new Set([...state.constrained,code])]:state.constrained.filter(c=>c!==code);if(adding)state.electives=state.electives.filter(c=>c!==code);}else if(kind==='education'){const pair=['O_MWRLDBS_1','O_MWRLDBS_2'],codes=pair.includes(code)?pair:[code];state.educationElectives=state.educationElectives.filter(c=>!codes.includes(c));if(adding)state.educationElectives.push(...codes);}else if(adding)state.electives.push(code);dirty=true;}
function projectDialog(key){if(!['major','minor','literature'].includes(key)||R.isEducation(state)&&key!=='major')return;const p=state[key],title=key==='major'?'Major Research Project Details':key==='minor'?'Minor Research Project Details':'Literature Thesis Details';const route=key==='major'&&!R.isEducation(state)?dialogSelect('route','Registration route *',p.route,[['','Choose one route'],['single','Single 48 EC course - year 2 (2027-2028)'],['split','Part 1: 18 EC + Part 2: 30 EC']],'required'):'';
 showDialog(title,`<div class="grid">${route}${dialogSelect('hostStatus','Host status *',p.hostStatus,[['','Make selection'],['proposed','Proposed'],['confirmed','Confirmed']],'required')}${dialogSelect('topicStatus','Topic status *',p.topicStatus,[['','Make selection'],['unknown','Not yet known'],['proposed','Proposed'],['confirmed','Confirmed']],'required')}${dialogFields('host','Host / institution *',p.host,'text','required maxlength="500"')}<div class="field full" id="topic-entry"><label for="dlg-topic">Topic *</label><textarea name="topic" id="dlg-topic" maxlength="10000">${esc(p.topic)}</textarea></div></div><p class="help">The project is added or updated only when you save these details.</p>`,f=>{const next={...p};for(const k of ['hostStatus','host','topicStatus','topic'])next[k]=clean(f.get(k));if(key==='major'&&!R.isEducation(state))next.route=clean(f.get('route'));next.enabled=true;if(key==='major')next.smcPreparationAcknowledged=false;state[key]=next;});
 const form=$('dialog-form');const refresh=()=>{const needed=['proposed','confirmed'].includes(form.elements.topicStatus.value);$('topic-entry').hidden=!needed;form.elements.topic.required=needed;markDialog();};form.onchange=refresh;refresh();
}
function customCourseRow(c){return `<tr data-custom-id="${esc(c.uid)}"><td><span class="course-name">${esc(c.name)||'Untitled course'}</span> <span class="unlisted-review-label">Unlisted course, needs review</span><span class="course-institution">${esc(c.institution)}</span>${/^https?:\/\/\S+$/i.test(c.url)?`<a class="syllabus-link" href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">Course syllabus</a>`:''}</td><td class="course-code">${esc(c.code)||'Required'}</td><td class="course-level">${esc(c.level)||'Required'}</td><td class="actions"><button class="row-action" data-action="edit-custom" data-id="${esc(c.uid)}" aria-label="Edit ${esc(c.name)}" title="Edit course details">${gearIcon()}</button><button class="row-action" data-action="remove-custom" data-id="${esc(c.uid)}" aria-label="Remove ${esc(c.name)}" title="Remove ${esc(c.name)}">${removeIcon()}</button></td><td class="ec">${esc(c.ec)||'-'}</td></tr>`;}
function customRows(rows=state.custom){return rows.length?courseRows([],{custom:rows}):'<p class="empty">No unlisted courses added.</p>';}
function educationUnlisted(component){const label=component==='dds'?'DDS':'Education';return `<button data-action="add-custom" data-component="${component}">Add an unlisted course</button><p class="help">Unlisted ${label} courses require individual Examination Board approval.${component==='dds'?' Alpha/gamma courses are not allowed in the DDS component.':''}</p>`;}
function educationElectives(){return `<section id="electives"><h2>6. Other elective courses</h2><p class="notice">Required split: 60 EC DDS + 60 EC Education. Extra credits need justification and approval. Alpha/gamma courses are not allowed in the DDS component.</p><div id="dds-elective-space"><h3>DDS electives · year 1</h3><p class="help">Use the remaining DDS space after Principles, the compulsory DDS courses, the 30 EC major and the 6 EC constrained choice. The unchosen constrained course is also available here.</p>${state.electives.length||state.custom.some(c=>c.component==='dds')?courseRows(state.electives,{removable:true,custom:state.custom.filter(c=>c.component==='dds')}):'<p class="empty">No DDS electives selected.</p>'}${picker('general')}${educationUnlisted('dds')}</div><div id="education-elective-space"><h3>Education electives · year 2 <span class="tag">6 EC required</span></h3><p class="help">Choose Praktijkonderzoek (6 EC) or two distinct 3 EC courses. <span class="required-mark">* Required elective space.</span> Wereldburgerschap and Wereldburgerschap deel 2 must be taken together. An unlisted Education course needs individual Examination Board approval.</p>${selectionBlock('education',R.educationSpec().educationElectives,state.educationElectives,state.custom.filter(c=>c.component==='education'))}${educationUnlisted('education')}${state.educationElectives.filter(c=>!R.educationSpec().educationElectives.includes(c)).map(c=>`<p class="warning-text">Unavailable Education elective: ${esc(R.map[c]?.name||c)} <button data-action="remove-education-elective" data-code="${esc(c)}">Remove</button></p>`).join('')}</div>${state.custom.some(c=>!['dds','education'].includes(c.component))?`<div class="notice"><h3>Unlisted courses needing a component</h3><p>Choose DDS or Education using Edit to place each imported course in the correct elective space.</p>${customRows(state.custom.filter(c=>!['dds','education'].includes(c.component)))}</div>`:''}</section>`;}
function electives(){if(R.isEducation(state))return educationElectives();const general=state.electives.filter(c=>R.map[c]?.category!=='alpha'),alpha=state.electives.filter(c=>R.map[c]?.category==='alpha');return `<section id="electives"><h2>6. Other elective courses</h2><p class="help">Elective courses except your own constrained electives are available here. If your preferred course is not available you can add it using the &quot;Add an unlisted course&quot; button below.</p><div id="general-elective-space"><h3>General electives</h3>${general.length||state.custom.some(c=>c.category==='general')?courseRows(general,{removable:true,custom:state.custom.filter(c=>c.category==='general')}):'<p class="empty">No general electives selected.</p>'}${picker('general')}${state.electives.includes('XM_0197')?'<p class="help">Didactics of Science Supervision: enrol in the same academic year as your supervision activities and plan the theoretical preparation in advance (period 1 or 3).</p>':''}</div><div id="alpha-elective-space"><h3>Alpha/gamma electives <span class="tag">Maximum 18 EC</span></h3><p class="help">Society, communication and related electives. Use + Add alpha/gamma elective to choose a common course. If you prefer another alpha/gamma course, you can add it through the &quot;Add an unlisted course&quot; button below.</p>${alpha.length||state.custom.some(c=>c.category==='alpha')?courseRows(alpha,{removable:true,custom:state.custom.filter(c=>c.category==='alpha')}):'<p class="empty">No alpha/gamma electives selected.</p>'}${picker('alpha')}</div>${state.educationElectives.length?`<h3>Education selections from another specialisation</h3><p class="notice warning-text">These selections are not available for this specialisation.</p>${state.educationElectives.map(c=>`<p>${esc(R.map[c]?.name||c)} <button data-action="remove-education-elective" data-code="${esc(c)}">Remove</button></p>`).join('')}`:''}<h3>Courses outside this catalogue</h3><p class="help">Complete all course details and choose the elective course type &quot;General&quot; or &quot;Alpha/gamma&quot;. The course will be assessed as part of the PEP review.</p>${state.custom.some(c=>!['general','alpha'].includes(c.category))?customRows(state.custom.filter(c=>!['general','alpha'].includes(c.category))):''}<button data-action="add-custom">Add an unlisted course</button></section>`;}
function submissionInstructions(){return `<p class="help approval-instructions">After downloading the completed PDF, send it by e-mail to your specialisation coordinator for completion and preapproval. Once you get the signed PEP form back from your specialisation coordinator, you should submit it to the DDS examination board for approval via:<br><a href="https://vu.nl/en/student/elective-space/electives" target="_blank" rel="noopener noreferrer">https://vu.nl/en/student/elective-space/electives</a></p>`;}
function reviewShell(){return `<section id="review"><h2>7. Review and Generate PDF for approval</h2><div id="review-results"></div><div class="grid" style="margin-top:24px"><div class="field"><label for="coordinator">Specialisation coordinator</label><input id="coordinator" value="${esc(R.coordinatorName(state))}" readonly placeholder="Select a specialisation">${R.isEducation(state)?'<p class="help">d.p.geerke@vu.nl · preapproves both the DDS and Education components.</p>':''}</div>${area('notes','Additional explanation (optional)')}<p id="exception-help" class="help full" hidden>Exception requests should use the relevant “Request exception” button above so the affected rule is clear.</p></div><div class="exports"><button id="download-pdf" class="primary" aria-describedby="pdf-availability">Download PDF for approval</button><button id="export-draft-bottom" data-action="export-draft"><svg class="action-icon" aria-hidden="true" focusable="false" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M5 3h12l4 4v14H3V3h2Z M7 3v6h10V3 M7 21v-8h10v8 M14 4v3"/></svg><span class="button-label">Save draft</span></button><button id="open-draft-bottom" data-action="open-draft"><svg class="action-icon" aria-hidden="true" focusable="false" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M3 7V4h6l2 3h10v3 M3 7v14h16l3-11H7L3 21"/></svg><span class="button-label">Open draft</span></button></div><p id="pdf-availability" class="pdf-availability" role="status" aria-live="polite"></p><details class="draft-help"><summary>How to use import and export functions</summary><p><strong>Save draft</strong> saves your entries as a JSON file. <strong>Open draft</strong> imports the draft PEP so you can continue editing later on. An exported curriculum planning generated with the <a href="https://dannyscholten.github.io/PEP-builder/" target="_blank" rel="noopener noreferrer">Personal Education Plan Builder</a> can also be imported via this button. Use <strong>Export for approval</strong> in PEP Builder. This imports the course selection; teaching periods stay in the Builder and are not added to Additional explanation. A <strong>Save build</strong> file is for reopening in PEP Builder and cannot be imported here.</p><p><strong>Note:</strong> Changes to this form are not saved automatically.</p><p><strong>Note:</strong> PDFs can be generated, but not be imported by this tool.</p></details>${submissionInstructions()}</section>`;}
const requiredMark='<span class="required-mark" aria-hidden="true"> *</span>';
const requiredNote='<p class="mandatory-note"><span class="required-mark" aria-hidden="true">*</span> Indicates a mandatory field.</p>';
function mandatory(path){
 if(['student.firstName','student.lastName','student.number','student.specialization','student.path','student.education','student.institution','student.degree','student.graduated','major.route','literature.code'].includes(path))return true;
 if(/^(major|minor|literature)\.(hostStatus|topicStatus)$/.test(path))return true;
 const match=/^(major|minor|literature)\.(host|topic)$/.exec(path);return !!match&&['proposed','confirmed'].includes(state[match[1]][match[2]+'Status']);
}
function markField(el,needed){
 el.required=needed;el.setAttribute('aria-required',String(needed));const label=el.id?document.querySelector('label[for="'+el.id+'"]'):null;if(!label)return;
 label.querySelectorAll('.required-mark').forEach(e=>e.remove());label.innerHTML=label.innerHTML.replace(/\s*\*\s*$/,'');if(needed)label.insertAdjacentHTML('beforeend',requiredMark);
}
function markRequired(){
 document.querySelectorAll('#main-content [data-bind]').forEach(el=>{if(el.type!=='checkbox')markField(el,mandatory(el.dataset.bind));});
 for(const id of ['cohort','coordinator'])markField($(id),true);
 document.querySelectorAll('#main-content>section').forEach(el=>el.insertAdjacentHTML('beforeend',requiredNote));
 if($('constrained').querySelector('.choices')&&!R.isEducation(state)){$('constrained').querySelector('.choices').insertAdjacentHTML('beforebegin','<p class="selection-label"><strong>Minimum of two constrained electives'+requiredMark+'</strong></p>');}
}
function markDialog(){$('editor').querySelectorAll('input[id],select[id],textarea[id]').forEach(el=>{if(el.type!=='checkbox')markField(el,el.required);});}
function render(){state.coordinator=R.coordinatorName(state);R.clearFixedCourseDetails(state);const y=window.scrollY;$('main-content').innerHTML=personal()+principles()+compulsory()+constrained()+projects()+electives()+reviewShell();markRequired();update();observeSections();window.scrollTo(0,y);}
function highlightSection(id){
 activeSection=id;
 document.querySelectorAll('.section-links a').forEach(a=>{const active=a.hash==='#'+id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});
}
function observeSections(){
 sectionObserver?.disconnect();
 sectionObserver=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>Math.abs(a.boundingClientRect.top-110)-Math.abs(b.boundingClientRect.top-110));if(visible.length)highlightSection(visible[0].target.id);},{rootMargin:'-100px 0px -65% 0px',threshold:0});
 document.querySelectorAll('#main-content>section').forEach(e=>sectionObserver.observe(e));highlightSection(activeSection);
}
window.matchMedia('(max-width:850px)').addEventListener('change',e=>{const nav=document.querySelector('.section-nav');if(nav)nav.open=!e.matches;});
function reviewGroupTitle(severity){return severity==='error'?'Items to complete by student':severity==='review'?'Items requiring review by admission board or specialisation coordinator':'Planning warnings';}
function update(){const v=R.evaluate(state);$('summary').innerHTML=`<h2>Total credit count of PEP</h2><div class="total ${v.total===120?'total-complete':v.total>=110&&v.total<120?'total-near':'total-alert'}">${fmt(v.total)} <small>/ 120 EC</small></div><div class="meter"><span style="width:${Math.min(100,v.total/120*100)}%;${v.total>120?'background:#a82525':''}"></span></div>${v.total<=120?`<p class="remaining">${v.total<120?fmt(120-v.total)+' EC remaining':'Credit total complete'}</p>`:''}<div class="aside-details"><h3>Credits per PEP section</h3>${['Principles courses','Compulsory courses','Constrained electives','Major research project','Minor research project','Literature thesis','General electives','Alpha/gamma electives','Education compulsory courses','Education electives','Electives awaiting classification'].map(label=>{let n=v.rows.filter(r=>r.section===label).reduce((a,r)=>a+r.ec,0);return n?`<div class="subtotal"><span>${R.isEducation(state)&&label==='General electives'?'DDS electives':label}</span><strong>${fmt(n)}</strong></div>`:''}).join('')}${R.isEducation(state)?`<div class="component-totals"><div class="subtotal"><span>DDS component</span><strong>${fmt(v.ddsTotal)} / 60 EC</strong></div><div class="subtotal"><span>Education component</span><strong>${fmt(v.educationTotal)} / 60 EC</strong></div></div><p class="help">No alpha/gamma courses in the DDS component.</p>`:''}</div><div class="status-messages"><h3>Status messages</h3><a class="subtotal status-link" href="${v.errors.length?'#messages-error':'#review'}"><span>Items to complete by student</span><strong class="${v.errors.length?'bad':'good'}">${v.errors.length}</strong></a><a class="subtotal status-link" href="${v.review.length?'#messages-review':'#review'}"><span>Decision / verification items</span><strong class="${v.review.length?'pending':'good'}">${v.review.length}</strong></a><a class="subtotal status-link" href="${v.warnings.length?'#messages-warning':smcReminderNeeded()?'#smc-preparation-reminder':'#review'}"><span>Planning warnings</span><strong class="${v.warnings.length+(smcReminderNeeded()?1:0)?'bad':'good'}">${v.warnings.length+(smcReminderNeeded()?1:0)}</strong></a></div><nav aria-label="Navigate PEP sections"><details class="section-nav" ${window.matchMedia('(min-width:851px)').matches?'open':''}><summary><h3>Navigate PEP sections</h3></summary><div class="section-links"><a href="#personal">1. Personal details</a><a href="#principles">2. Principles courses</a><a href="#compulsory">3. Compulsory courses</a><a href="#constrained">4. Constrained electives</a><a href="#projects">5. ${R.isEducation(state)?'Major research project':'Research projects and literature thesis'}</a><a href="#electives">6. Other elective courses</a><a href="#review">7. Review and Generate PDF for approval</a></div></details></nav>`;
 $('review-results').innerHTML=`<div class="review-panel"><h3>Curriculum checks</h3><div class="check-grid">${v.checks.map(c=>`<article class="check-card" data-status="${c.status}"><div class="check-heading"><h4 class="check-title">${esc(c.label)}</h4><span class="check-status ${c.status}">${c.status==='pass'?'Passed':c.status==='error'?'Action needed':'Decision required'}</span></div><p class="check-value">${esc(c.value)}</p><p class="help">${esc(c.description)}</p></article>`).join('')}</div></div>${v.issues.length?['error','review','warning'].filter(severity=>v.issues.some(i=>i.severity===severity)).map(severity=>`<div id="messages-${severity}" class="review-panel review-${severity}"><h3>${reviewGroupTitle(severity)}</h3><ul class="review-list">${v.issues.filter(i=>i.severity===severity).map(i=>`<li><span class="issue-type ${i.severity}">${i.severity==='error'?'Action needed':i.severity==='review'?'Decision / verification required':'Planning warning'}</span><p class="issue-message ${i.severity==='warning'||i.severity==='error'?'warning-text':''}">${esc(i.message)}</p>${i.requested?`<p class="issue-message exception-justification"><strong>Exception requested:</strong> ${esc(i.reason)}</p>${i.reference?`<p class="help">Reference: ${esc(i.reference)}</p>`:''}`:''}<div class="issue-actions"><a href="#${i.section}" class="help">Go to section</a>${i.exceptionable?`<button class="quiet small" data-action="exception" data-id="${esc(i.id)}">${i.requested?'Edit exception request':'Request exception'}</button>`:''}</div></li>`).join('')}</ul></div>`).join(''):'<p class="help">No automatic composition issues found. Coordinator preapproval and Examination Board approval are still required.</p>'}${v.inactiveRequests.length?`<p class="help">${v.inactiveRequests.length} saved exception request(s) no longer apply to the current selections and will not appear as active requests in the PDF.</p>`:''}${smcReminder()}`;
 const exceptionHelp=$('exception-help');if(exceptionHelp)exceptionHelp.hidden=!v.issues.some(i=>i.exceptionable);
 for(const id of ['download-pdf']){const btn=$(id);if(btn)btn.disabled=!v.canExport;}
 const availability=$('pdf-availability');availability.hidden=!v.canExport;availability.classList.toggle('unavailable',!v.canExport);availability.textContent=v.canExport?(v.review.length?'Available for download. Decision / verification items in the PDF still require review and preapproval.':'Available for download. Send the PDF by e-mail to your specialisation coordinator for preapproval.'):'Not yet available: complete the '+v.errors.length+' item'+(v.errors.length===1?'':'s')+' listed under “Items to complete by student” above. Fill in required details and resolve blocking checks, or add a justified exception where offered.';
 $('download-pdf').title=availability.textContent;
 highlightSection(activeSection);document.querySelector('.save-note').textContent=dirty?'Unsaved changes - use Save draft':'Changes are not saved automatically';
}
function dialogFields(name,label,value,type='text',extra=''){return `<div class="field"><label for="dlg-${name}">${label}</label><input id="dlg-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function dialogSelect(name,label,value,options,extra=''){return `<div class="field"><label for="dlg-${name}">${label}</label><select id="dlg-${name}" name="${name}" ${extra}>${options.map(([v,l])=>`<option value="${v}" ${value===v?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;}
function showDialog(title,body,onSave){const returnId=document.activeElement?.id;$('editor').innerHTML=`<button class="dialog-close" type="button" id="dlg-close" aria-label="Close dialog">Close</button><h2 id="dialog-title">${esc(title)}</h2><form id="dialog-form">${body}${requiredNote}<div class="buttons"><button type="button" id="dlg-cancel">Cancel</button><button class="primary" type="submit">Save</button></div></form>`;$('dlg-close').onclick=$('dlg-cancel').onclick=()=>{$('editor').close();$(returnId)?.focus({preventScroll:true});};$('dialog-form').onsubmit=e=>{e.preventDefault();onSave(new FormData(e.target));dirty=true;$('editor').close();render();($(returnId)||$(returnId?.replace('add-','edit-project-')))?.focus({preventScroll:true});};markDialog();$('dialog-form').onchange=()=>markDialog();$('editor').showModal();}
const clean=v=>String(v??'').trim();
function customDialog(uid,component=''){
 const old=state.custom.find(c=>c.uid===uid),c=old||{uid:'C'+Date.now().toString(36)+Math.random().toString(36).slice(2,5),name:'',code:'',institution:'',ec:'',level:'',category:'',component,url:''};
 showDialog(old?'Edit unlisted course':'Add an unlisted course',`<p class="help">All seven fields are required.</p><div class="grid">${dialogFields('name','Course title *',c.name,'text','required maxlength="500"')}${dialogFields('institution','Institution *',c.institution,'text','required maxlength="500"')}${dialogFields('code','Course code *',c.code,'text','required maxlength="100"')}${dialogFields('ec','EC *',c.ec,'number','required min="0.01" max="120" step="0.01"')}${dialogFields('level','Academic level *',c.level,'text','required maxlength="80" list="academic-levels" placeholder="e.g. 400, 500, 600 or equivalent"')}<datalist id="academic-levels"><option value="400"><option value="500"><option value="600"></datalist>${R.isEducation(state)?dialogSelect('component','PEP component *',c.component||'',[['','Choose DDS or Education'],['dds','DDS - scientific course; no alpha/gamma'],['education','Education']],'required'):dialogSelect('category','Elective category *',c.category,[['','Choose a category'],['general','General elective'],['alpha','Alpha/gamma elective']],'required')}<div class="full">${dialogFields('url','Public syllabus URL *',c.url,'url','required pattern="[hH][tT][tT][pP][sS]?://.+"')}</div></div><p class="help" style="margin-top:12px">Course suitability, overlap and classification are assessed during PEP review. Select existing catalogue courses from the list.</p>`,f=>{
  const updated={uid:c.uid};for(const key of ['name','institution','code','ec','level','category','url'])updated[key]=clean(f.get(key));
  if(R.isEducation(state)){updated.component=clean(f.get('component'));updated.category=updated.component==='education'?'education':'general';}
  state.custom=state.custom.filter(x=>x.uid!==c.uid);state.custom.push(updated);
 });
}
function exceptionDialog(id){const issue=R.evaluate(state).issues.find(i=>i.id===id);if(!issue?.exceptionable)return;const ex=state.exceptions[id]||{};showDialog('Request an exception',`<p>${esc(issue.message)}</p><p class="help">This request will appear in the PDF as “decision required”.</p>${ex.reason?'<button type="button" class="quiet danger" id="remove-exception">Remove exception request</button>':''}<div class="field" style="margin-top:16px"><label for="dlg-reason">Justification</label><textarea id="dlg-reason" name="reason" maxlength="10000" required>${esc(ex.reason||'')}</textarea><p class="help">Explain why the departure is necessary. A justification is mandatory for an exception request.</p></div><div style="margin-top:14px">${dialogFields('reference','Supporting reference, if available',ex.reference||'')}</div>`,f=>{const reason=clean(f.get('reason'));if(reason)state.exceptions[id]={reason,reference:clean(f.get('reference'))};else delete state.exceptions[id];});if($('remove-exception'))$('remove-exception').onclick=()=>{delete state.exceptions[id];dirty=true;$('editor').close();render();};}
function download(name,text,type='application/json'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function filename(){return 'DDS_PEP_'+(state.student.number||'draft').replace(/[^a-zA-Z0-9_-]/g,'_')+'_'+new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Amsterdam'});}
function saveDraft(){const saved=R.exportDraft(state);download(filename()+'.json',JSON.stringify(saved,null,2));dirty=false;update();toast('Your entries were saved to a separate JSON draft file. Use Open draft to restore them later.');}
async function openFile(file){if(!file)return;if(file.size>2*1024*1024){toast('This file is too large to be a PEP draft (maximum 2 MB).');return;}try{const raw=JSON.parse(await file.text()),imported=R.importDraft(raw);if(dirty&&!confirm('Opening a draft will replace your unsaved changes. Continue?'))return;state=imported;dirty=false;render();$('student-firstName').focus();toast(raw.plannerTransfer?'PEP Builder selection imported: '+R.evaluate(state).total+' EC. Complete your personal and project details. All approval checks have been recalculated.':'Draft imported. All checks have been recalculated.');}catch(e){toast('Could not open draft: '+e.message);}finally{$('file-input').value='';}}
function action(e){const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const {action,code,id,category}=b.dataset;
 if(action==='remove-education-minor'){state.minor.enabled=false;dirty=true;render();}
 if(action==='pick-course')coursePicker(b.dataset.kind);
 if(action==='add-choice'){const kind=b.dataset.kind;if(!pickerCodes(kind).includes(code))return;changeSelection(kind,code,true);render();coursePicker(kind,true,R.map[code].name+' added to your PEP.');}
 if(action==='close-picker'){$('editor').close();$(pickerReturnId)?.focus({preventScroll:true});}
 if(action==='acknowledge-smc'){state.major.smcPreparationAcknowledged=true;dirty=true;render();}
 if(['remove-principles','remove-constrained','remove-education'].includes(action)){changeSelection(action.slice(7),code,false);render();}
 if(action==='project')projectDialog(b.dataset.key);
 if(action==='remove-project'){const key=b.dataset.key;if(['major','minor','literature'].includes(key)){state[key].enabled=false;if(key==='major'){state.major.route='';state.major.smcPreparationAcknowledged=false;}dirty=true;render();}}
 if(action==='remove-education-elective'){state.educationElectives=state.educationElectives.filter(c=>c!==code);dirty=true;render();}
 if(action==='remove-elective'){state.electives=state.electives.filter(c=>c!==code);dirty=true;render();}
 if(action==='add-custom')customDialog(undefined,b.dataset.component||'');
 if(action==='edit-custom')customDialog(id);
 if(action==='remove-custom'){if(confirm('Remove this unlisted course?')){state.custom=state.custom.filter(c=>c.uid!==id);dirty=true;render();}}
 if(action==='exception')exceptionDialog(id);
}
function changed(e){
 const el=e.target;
 const path=el.dataset.bind;if(!path)return;
 if(el.tagName==='INPUT'&&el.type!=='checkbox'||el.tagName==='TEXTAREA')return;
 const value=el.type==='checkbox'?el.checked:el.value;
 if(path==='student.specialization'){
  if(state.student.specialization&&value!==state.student.specialization&&!confirm('Changing specialisation updates the compulsory courses. Your current elective choices will be retained where applicable. Education has a fixed 30 EC major and does not allow a minor; switching to Education removes the minor and literature thesis from the plan. Other unavailable choices will need correction. Continue?')){el.value=state.student.specialization;return;}
  const pool=[...new Set([...state.constrained,...state.electives])];set(path,value);state.student.path='';state.constrained=[];
  state.electives=pool.filter(c=>!R.requiredCodes(state).includes(c));R.organiseConstrained(state);
  if(R.isEducation(state)){state.major.route='';state.major.enabled=false;state.major.smcPreparationAcknowledged=false;state.minor.enabled=false;state.literature={...R.fresh().literature};}
 }else if(path==='student.path'){R.selectPath(state,value);state.major.smcPreparationAcknowledged=false;dirty=true;}
 else if(path==='student.education'){
  const previous=state.student.education;set(path,value);
  if(value==='VU_FW'){state.student.institution='Vrije Universiteit Amsterdam';state.student.degree='Farmaceutische Wetenschappen';}else if(previous==='VU_FW'){state.student.institution='';state.student.degree='';}
  state.principles={override:['WO','HBO'].includes(value),required:['WO','HBO'].includes(value)?[...D.principles]:[]};
 }
 else set(path,value);
 render();const focus=document.getElementById(el.id);if(focus)focus.focus({preventScroll:true});
}
function inputted(e){const el=e.target;if(!el.dataset.bind||el.type==='checkbox'||el.tagName==='SELECT')return;set(el.dataset.bind,el.type==='number'?Number(el.value):el.value);update();}
function printCourseTable(rows){return `<table class="print-table"><thead><tr><th>Course / component</th><th class="code">Course code</th><th>Level</th><th class="ec">EC</th></tr></thead><tbody>${rows.map(r=>{const detail=R.isFixedCourse(state,r.id)?undefined:state.courseDetails[r.id],bits=[];if(r.project){const key=r.section==='Major research project'?'major':r.section==='Minor research project'?'minor':'literature',p=state[key],detail=field=>p[field+'Status']==='unknown'?'Not yet known':!p[field+'Status']?'Not selected':p[field]+' ('+p[field+'Status']+')';bits.push('Host: '+detail('host'),'Topic: '+detail('topic'));}if(r.custom){bits.push('Institution: '+r.institution+' · Level: '+r.level);bits.push(R.isEducation(state)?'Component: '+(r.component==='education'?'Education':'DDS'):'Category: '+(r.category==='alpha'?'Alpha/gamma':r.category==='general'?'General':'Not supplied'));if(r.url)bits.push(r.url);}if(detail?.outside){bits.push('Outside VU: '+detail.institution);bits.push(detail.url);}return `<tr><td>${esc(r.name)}${r.custom?'<br><span class="unlisted-review-label">Unlisted course, needs review</span>':''}${bits.length?'<br><small>'+bits.map(esc).join('<br>')+'</small>':''}</td><td>${esc(r.code)}</td><td>${esc(r.level??(r.project?(r.id==='MINOR'?500:600):'-'))}</td><td class="ec">${fmt(r.ec)}</td></tr>`;}).join('')}</tbody></table>`;}
function printProject(key,label){const p=state[key],detail=field=>p[field+'Status']==='unknown'?'Not yet known':!p[field+'Status']?'Not selected':p[field]+' ('+p[field+'Status']+')';return `<div class="print-project"><p><strong>${esc(label)}</strong></p><table class="print-table"><tbody><tr><td class="label">Host</td><td>${esc(detail('host'))}</td></tr><tr><td class="label">Topic</td><td>${esc(detail('topic'))}</td></tr></tbody></table></div>`;}
function resourceLinks(){return `<p class="resource-links"><a href="${D.links.studyGuide}" target="_blank" rel="noopener noreferrer">VU Study Guide - TER</a><span> · </span><a href="${D.links.canvas}" target="_blank" rel="noopener noreferrer">DDS Canvas community</a></p>`;}
function pdfCheckDescription(c){if(c.id!=='courses')return c.description;const codes=[...R.requiredCodes(state).filter(code=>!D.principles.includes(code)),...(R.isEducation(state)?R.educationSpec().educationCompulsory:[])];return c.description+' Compulsory courses: '+[...new Set(codes)].map(code=>R.map[code].name+' ('+code+', '+R.map[code].ec+' EC)').join('; ')+'.';}
function coordinatorExceptions(v){return v.issues.filter(i=>i.exceptionable&&i.requested);}
function preparePrint(mode){const v=R.evaluate(state),exceptions=coordinatorExceptions(v);const draft=mode==='draft'||!v.canExport;const time=new Date().toLocaleDateString('en-GB',{timeZone:'Europe/Amsterdam',day:'numeric',month:'long',year:'numeric'});let sections='';
 const info=[['First name',state.student.firstName],['Last name',state.student.lastName],['Student number',state.student.number],['Specialisation',D.names[state.student.specialization]||'Not selected'],...(state.student.path?[['Path',D.paths[state.student.path]||state.student.path]]:[]),['Cohort','2026'],['Previous education',(state.student.education==='VU_FW'?'VU bachelor Farmaceutische Wetenschappen':state.student.education==='HBO'?'HBO diploma':'University bachelor')+' - '+state.student.institution+'; '+state.student.degree+'; graduation '+state.student.graduated]];
 sections+=`<section class="print-section"><h2>1. Personal details</h2><table class="print-table"><tbody>${info.map(([a,b])=>`<tr><td class="label">${esc(a)}</td><td>${esc(b)||'Not supplied'}</td></tr>`).join('')}</tbody></table></section>`;
 if(state.student.education!=='VU_FW')sections+=`<section class="print-section"><h2>2. Principles courses</h2>${v.principles.length?printCourseTable(v.rows.filter(r=>r.section==='Principles courses')):'<p>'+(state.student.education?'Neither Principles course included (0 EC).':'Previous education not selected.')+'</p>'}${v.principlesStatementRequired?'<p>The Admissions Board records its decision in the Decisions and explanations area before signing.</p>':v.principles.length===2?'<p>Both Principles courses are included. No Admissions Board decision or signature is required.</p>':''}</section>`;
 sections+=`<section class="print-section"><h2>3. Compulsory courses</h2>${printCourseTable(v.rows.filter(r=>r.section==='Compulsory courses'&&!D.principles.includes(r.code)))}${R.isEducation(state)?`<h3>Education compulsory courses · 54 EC</h3>${printCourseTable(v.rows.filter(r=>r.section==='Education compulsory courses'))}`:''}</section>`;
 sections+=`<section class="print-section"><h2>4. Constrained electives</h2>${printCourseTable(v.rows.filter(r=>r.section==='Constrained electives'))}<p>${R.isEducation(state)?'Choose one of the two courses (6 EC); the other may use DDS elective space.':'Minimum two of the six courses; required path courses must be included.'} Selected: ${state.constrained.length} courses (${state.constrained.reduce((n,c)=>n+(R.map[c]?.ec||0),0)} EC).</p></section>`;
 sections+=`<section class="print-section"><h2>5. ${R.isEducation(state)?'Major research project':'Research projects and literature thesis'}</h2>${printCourseTable(v.rows.filter(r=>['Major research project','Minor research project','Literature thesis'].includes(r.section)))}<p>Major registration route: ${R.isEducation(state)?'Fixed 30 EC Education major (XM_0200).':state.major.route==='split'?'18 EC Part 1 in 2026-2027 (XM_0207) + 30 EC Part 2 in 2027-2028 (to be announced).':state.major.route==='single'?'Single 48 EC course in 2027-2028 (to be announced).':'Not selected; the 48 EC are not counted.'}</p>${state.student.path==='SMC'?'<p class="smc-reminder">For a Synthetic Radiopharmaceutical Chemistry internship, Advanced Radiopharmaceutical Chemistry is required preparation. Discuss this with the internship coordinator.</p>':''}</section>`;
 sections+=`<section class="print-section"><h2>6. Other elective courses</h2>${['General electives','Alpha/gamma electives','Education electives','Electives awaiting classification'].map(label=>{const rows=v.rows.filter(r=>r.section===label);return rows.length?`<h3>${R.isEducation(state)&&label==='General electives'?'DDS electives':label}${label==='Alpha/gamma electives'?' - maximum 18 EC':''}</h3>${printCourseTable(rows)}<p style="text-align:right"><strong>Subtotal: ${fmt(rows.reduce((a,r)=>a+r.ec,0))} EC</strong></p>`:''}).join('')}${R.isEducation(state)?`<h3>Component credit totals</h3><table class="print-table component-credit-table"><tbody><tr><td class="label">DDS component</td><td>${fmt(v.ddsTotal)} / 60 EC</td></tr><tr><td class="label">Education component</td><td>${fmt(v.educationTotal)} / 60 EC</td></tr></tbody></table><p>Alpha/gamma courses are not permitted in the DDS component. dr. Daan Geerke (d.p.geerke@vu.nl) preapproves both components.</p>`:''}<p class="print-total"><span class="total-label">Total credit count of PEP</span><strong>${fmt(v.total)} EC</strong></p></section>`;
 sections+=`<section class="print-section"><h2>7. Review and Generate PDF for approval</h2><p><strong>${esc(v.status)}</strong>. Automatic checks do not constitute preapproval or Examination Board approval.</p><h3>Curriculum checks</h3><table class="print-table print-check-table"><thead><tr><th>Check</th><th>Details</th><th>Status</th></tr></thead><tbody>${v.checks.map(c=>`<tr data-status="${c.status}"><td><strong class="check-title">${esc(c.label)}</strong><br><small>${esc(pdfCheckDescription(c))}</small></td><td>${esc(c.value)}</td><td class="check-status ${c.status}">${c.status==='pass'?'Passed':c.status==='review'?'Decision required':'Action needed'}</td></tr>`).join('')}</tbody></table>${v.issues.length?'<p>Full warnings and decision statements are grouped at the end of this PDF.</p>':''}${state.notes?`<div class="print-review-item"><strong>Additional explanation (optional)</strong><p>${esc(state.notes)}</p></div>`:''}<p class="print-checks">Exemptions are requested separately; the exempted course remains included in this PEP.</p></section>`;
 if(v.principlesStatementRequired||exceptions.length)sections+=`<section class="print-section print-decisions"><h3>Decisions and explanations</h3><p>Relevant reviewers complete the fields below before signing. See the full warnings and decision statements at the end of this PDF.</p>${v.principlesStatementRequired?`<div class="admissions-explanation"><p>Admissions Board: record the decision permitting omission of one or both Principles courses.</p><div class="print-decision" data-pdf-field="admissions_decision"><p><strong>Admissions Board decision${requiredMark}</strong></p></div></div>`:''}${exceptions.length?`<div class="coordinator-exceptions"><p>Applicable exceptions: ${exceptions.map(i=>esc(i.id==='over120'?'Programme total '+fmt(v.total)+' EC (above 120 EC)':i.id==='constrained_min'?'Fewer than two constrained electives':i.id==='path_courses'?'Missing mandatory path courses':i.id==='alpha_limit'?'Alpha/gamma electives above 18 EC':'Course flagged for prohibited overlap')).join('; ')}.</p><p>Specialisation coordinator: briefly explain why you support these exceptions.</p><div data-pdf-field="coordinator_exception_comment"><p><strong>Coordinator explanation${requiredMark}</strong></p></div></div>`:''}</section>`;
 sections+=`<section class="print-section print-approval"><h3>Signatures</h3><p class="print-checks">${v.principlesStatementRequired?'The Admissions Board completes its decision and signs first. The specialisation coordinator then signs the PEP.':'The specialisation coordinator completes the date and signs the PEP.'}</p><table class="print-table signature-table"><thead><tr>${v.principlesStatementRequired?'<th>Admissions Board for Principles courses</th>':''}<th>Specialisation coordinator preapproval for PEP</th></tr></thead><tbody><tr>${v.principlesStatementRequired?`<td><strong>Name:${requiredMark}</strong></td>`:''}<td><strong>Name:</strong> ${esc(R.coordinatorName(state))}</td></tr><tr>${v.principlesStatementRequired?`<td class="signature-space"><strong>Signature:${requiredMark}</strong></td>`:''}<td class="signature-space"><strong>Signature:${requiredMark}</strong></td></tr><tr>${v.principlesStatementRequired?`<td><strong>Date:${requiredMark}</strong></td>`:''}<td><strong>Date:${requiredMark}</strong></td></tr></tbody></table><p class="print-checks mandatory-note">* Mandatory for the relevant signatory. Use the downloaded PDF for digital signing in Adobe Acrobat.</p><p class="print-checks">Changes require renewed preapproval by the specialisation coordinator. Pending exception requests remain subject to a decision by the examination board. A signed document by the specialisation coordinator does not guarantee approval by the examination board.</p></section>`;
 if(v.issues.length)sections+=`<section class="print-section print-review-appendix"><h2>Warnings and decision statements</h2><p>Full statements for the review items and any requested exceptions. Review labels do not constitute Examination Board approval.</p>${['error','review','warning'].flatMap(severity=>v.issues.filter(i=>i.severity===severity)).map((i,index,issues)=>`${index===0||issues[index-1].severity!==i.severity?`<h3>${reviewGroupTitle(i.severity)}</h3>`:''}<div class="print-review-item print-message-card ${i.severity}" ${i.severity==='review'?`data-review-id="${esc(i.id)}"`: ''}><strong>${i.severity==='error'?'ACTION NEEDED':i.severity==='review'?'DECISION / VERIFICATION REQUIRED':'PLANNING WARNING'}</strong><p class="${i.severity==='warning'||i.severity==='error'?'warning-text':''}">${esc(i.message)}</p>${i.requested?`<p class="exception-justification"><strong>Exception requested:</strong> ${esc(i.reason)}</p>${i.reference?`<p class="exception-justification">Supporting reference: ${esc(i.reference)}</p>`:''}`:''}</div>`).join('')}</section>`;
 $('print-area').innerHTML=`<div class="print-head"><div><p>Master Drug Discovery Sciences</p><h1>Personal Education Plan Approval</h1>${resourceLinks()}</div><img src="${logo}" alt="Vrije Universiteit Amsterdam"></div>${draft?'<p class="print-watermark">DRAFT - NOT FOR SUBMISSION</p>':''}<p class="print-meta">Date generated: ${esc(time)}</p><div class="print-submission">${submissionInstructions()}</div>${sections}`;
 $('print-area').querySelectorAll('.print-section>h2').forEach((h,i)=>h.textContent=h.textContent.replace(/^\d+\. /,(i+1)+'. '));
 return v;
}
async function downloadPDF(){
 const snapshot=JSON.parse(JSON.stringify(state)),v=R.evaluate(snapshot);if(!v.canExport){toast('Complete the action-needed items or provide a permitted exception request first.');return;}
 const btn=$('download-pdf');btn.disabled=true;btn.textContent='Preparing PDF…';$('pdf-availability').textContent='Preparing your PDF…';
 try{preparePrint('review');const root=$('print-area').cloneNode(true);const name=filename();const bytes=await window.PEP_PDF.create(root,snapshot,logo);download(name+'.pdf',bytes,'application/pdf');toast('PDF downloaded. Send it by e-mail to your specialisation coordinator for completion and preapproval.');}
 catch(e){toast('PDF download failed: '+e.message+' Export your draft to keep your entries and report the issue using the link at the bottom of the form.');}
 finally{btn.textContent='Download PDF for approval';update();}
}
function cancelOnBackdrop(dialog){let outsideStart=false;const outside=e=>{const r=dialog.getBoundingClientRect();return e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom;};dialog.addEventListener('pointerdown',e=>{outsideStart=e.target===dialog&&outside(e);});dialog.addEventListener('click',e=>{if(outsideStart&&e.target===dialog&&outside(e))dialog.close();outsideStart=false;});}
cancelOnBackdrop($('editor'));cancelOnBackdrop($('welcome-dialog'));
$('editor').addEventListener('click',action);
$('main-content').addEventListener('input',inputted);$('main-content').addEventListener('change',changed);$('main-content').addEventListener('click',e=>{const button=e.target.closest('button');action(e);if(button?.dataset.action==='export-draft')saveDraft();if(button?.dataset.action==='open-draft')$('file-input').click();if(button?.id==='download-pdf')downloadPDF();});
$('save-draft').onclick=saveDraft;$('open-draft').onclick=()=>$('file-input').click();$('file-input').onchange=e=>openFile(e.target.files[0]);
$('review-button').onclick=()=>{$('review').scrollIntoView({behavior:'smooth'});$('review').setAttribute('tabindex','-1');$('review').focus({preventScroll:true});};
$('new-plan').onclick=()=>{if(confirm('Reset form? All entries and selections will be cleared. Save your draft first if you want to keep a copy.')){state=R.fresh();dirty=false;render();window.scrollTo(0,0);}};
window.addEventListener('beforeprint',()=>preparePrint('review'));
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
document.querySelector('.masthead h1').insertAdjacentHTML('afterend',resourceLinks());
$('form-version').textContent='Form version '+D.appVersion+' · '+D.releaseDate;
render();
const welcome=$('welcome-dialog'),welcomeKey='dds-pep-introduction-hidden';
function rememberWelcome(){try{if($('welcome-hide').checked)localStorage.setItem(welcomeKey,'yes');else localStorage.removeItem(welcomeKey);}catch(e){/* The introduction still works when browser storage is unavailable. */}}
$('welcome-hide').onchange=rememberWelcome;
$('welcome-close').onclick=()=>{rememberWelcome();welcome.close();};
$('welcome-start').onclick=()=>{rememberWelcome();welcome.close();$('student-firstName').focus({preventScroll:true});};
welcome.addEventListener('close',rememberWelcome);
$('getting-started').onclick=()=>welcome.showModal();
let hideWelcome=false;try{hideWelcome=localStorage.getItem(welcomeKey)==='yes';}catch(e){}
$('welcome-hide').checked=hideWelcome;if(!hideWelcome)welcome.showModal();
// Exposes the same deterministic functions for local automated verification; no network access.
window.PEP_APP={getState:()=>JSON.parse(JSON.stringify(state)),load:s=>{state=R.importDraft(s);dirty=false;render();},evaluate:()=>R.evaluate(state),preparePrint,downloadPDF};
})();
